      method: "GET",
      url: `/api/cqrs/posts/${TEST_POST_ID}`,
    });

    expect(response1.statusCode).toBe(200);
    expect(response2.statusCode).toBe(200);

    const body2 = JSON.parse(response2.body);
    expect(body2.metadata.fromCache).toBeTruthy();
