    const integration = new CQRSIntegration({
      fastify,
      createPostUseCase: new MockCreatePostUseCase() as any,
      updatePostUseCase: new MockUpdatePostUseCase() as any,
      deletePostUseCase: new MockDeletePostUseCase() as any,
