      method: "POST",
      url: "/ai/optimize",
      payload: {
        content: "Test",
        platform: "",
      },
    });

    expect(response.statusCode).toBe(400);
  });

  it("should reject missing required fields", async () => {
    const response = await app.inject({
      method: "POST",
      url: "/ai/optimize",
      payload: {
        content: "Test",
      },
    });

    expect(response.statusCode).toBe(400);
  });
});

