    const response = await app.inject({
      method: "POST",
      url: "/ai/generate",
      payload: {
        messages: [{ role: "user", content: "Test" }],
      },
    });

    expect(response.statusCode).toBe(500);
    const body = JSON.parse(response.body);
    expect(body.ok).toBe(false);
  });
});

